"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[753],{6860:(e,a,i)=>{i.d(a,{A:()=>r});var t=i(5155);i(2115);var n=i(2821),o=i(8054),s=i(9498);let r=e=>{let{fit:a="cover",src:i,alt:r="",className:l,layout:u="top-right",badgeVariant:d="",badgeSize:c="",badgeContent:m="",svgCode:p}=e,k=(0,n.A)("w-full h-full flex items-center justify-center",{"object-cover":"cover"===a,"object-contain":"contain"===a}),f=(0,n.A)("absolute",{"top-2 left-2":"top-left"===u,"top-2 right-2":"top-right"===u,"bottom-2 left-2":"bottom-left"===u,"bottom-2 right-2":"bottom-right"===u,"top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2":"center"===u});return(0,t.jsxs)("div",{className:(0,s.cn)("relative flex w-full h-full overflow-hidden "+l),children:[p&&(0,t.jsx)("div",{className:k+"",dangerouslySetInnerHTML:{__html:p}}),i&&(0,t.jsx)("img",{src:i,alt:r,className:k}),m&&(0,t.jsx)(o.E,{className:f,variant:d,size:c,children:m})]})}},7788:(e,a,i)=>{i.d(a,{c:()=>t});let t=[{escaperoomname:"theClickTrap",category:"escaperoom",theme_en:"media literacy",theme_es:"alfabetizaci\xf3n medi\xe1tica",theme_fi:"medialukutaito",theme_sr:"medijska pismenost",title_en:"The Click Trap",title_es:"The Click Trap",title_fi:"The Click Trap",title_sr:"The Click Trap",duration_en:"1 hour",duration_es:"1 hora",duration_fi:"1 tunti",duration_sr:"1 sat",level_en:"easy",level_es:"f\xe1cil",level_fi:"helppo",level_sr:"lako",moreInfo_en:"more info",moreInfo_es:"m\xe1s info",moreInfo_fi:"lis\xe4tietoja",moreInfo_sr:"više informacija",longdescription_en:"At ConnectNow, a well-known influencer agency and content producer, rumours are beginning to circulate about suspicious activities: secret meetings, restricted areas and unethical agreements. Your friend Lena, an independent influencer who works with them, suspects that some people are promoting a supplement called GlowUp+ using misleading health and nutrition information, putting young people at risk. To help her, you infiltrate the company as a janitor to obtain evidence from within—documents, photos, and digital records—before they are deleted. The goal of the game is to uncover and expose how economic interests and irresponsible content creation fuel misinformation, encouraging critical thinking and source verification.",longdescription_es:"En ConnectNow, una conocida agencia de influencers y productora de contenidos, comienzan a circular rumores sobre actividades sospechosas: reuniones secretas, \xe1reas restringidas y acuerdos poco \xe9ticos. Tu amiga Lena, una influencer independiente que colabora con ellos, sospecha que algunos est\xe1n promoviendo un suplemento llamado GlowUp+ mediante informaci\xf3n enga\xf1osa sobre salud y alimentaci\xf3n, poniendo en riesgo a los j\xf3venes. Para ayudarla, te infiltras como conserje para obtener pruebas desde dentro —documentos, fotos y registros digitales— antes de que los borren. El objetivo del juego es descubrir y exponer c\xf3mo los intereses econ\xf3micos y la creaci\xf3n irresponsable de contenido alimentan la desinformaci\xf3n, fomentando el pensamiento cr\xedtico y la verificaci\xf3n de fuentes.",longdescription_fi:"ConnectNow, tunnettu vaikuttajien agentuuri ja sis\xe4ll\xf6ntuottaja, on alkanut kiert\xe4\xe4 huhuja ep\xe4ilytt\xe4vist\xe4 toimista: salaisista kokouksista, rajoitetuista alueista ja ep\xe4eettisist\xe4 sopimuksista. Yst\xe4v\xe4si Lena, itsen\xe4inen vaikuttaja, joka tekee yhteisty\xf6t\xe4 heid\xe4n kanssaan, ep\xe4ilee, ett\xe4 jotkut mainostavat GlowUp+ -nimist\xe4 ravintolis\xe4\xe4 antamalla harhaanjohtavaa tietoa terveydest\xe4 ja ravitsemuksesta, mik\xe4 vaarantaa nuorten terveyden. Auttaaksesi h\xe4nt\xe4 soluttaudut talonmieheksi ker\xe4\xe4m\xe4\xe4n todisteita sis\xe4lt\xe4p\xe4in – asiakirjoja, valokuvia ja digitaalisia tietoja – ennen kuin ne tuhotaan. Pelin tavoitteena on paljastaa, kuinka taloudelliset intressit ja vastuuton sis\xe4ll\xf6ntuotanto ruokkivat v\xe4\xe4r\xe4\xe4 tietoa, ja kannustaa kriittiseen ajatteluun ja l\xe4hteiden tarkistamiseen.",longdescription_sr:"U ConnectNow-u, poznatoj agenciji za influensere i produkciju sadržaja, počinju da kruže glasine o sumnjivim aktivnostima: tajnim sastancima, ograničenim zonama i neetičkim dogovorima. Tvoja prijateljica Lena, nezavisna influenserka koja sarađuje sa njima, sumnja da neki promovišu suplement pod nazivom GlowUp+ koristeći obmanjujuće informacije o zdravlju i ishrani, dovodeći mlade u rizik. Da bi joj pomogao, infiltriraš se kao domar kako bi iznutra pribavio dokaze — dokumenta, fotografije i digitalne zapise — pre nego što ih obrišu. Cilj igre je otkriti i razotkriti kako ekonomski interesi i neodgovorna produkcija sadržaja podstiču dezinformacije, negujući kritičko razmišljanje i proveru izvora.",learningObjectives_en:["Encourage critical thinking among students.","Reflect on how we use social media and the level of truthfulness we attribute to the content we see on it.","Question the role and influence that influencers have on us.","Prevent young people from falling prey to misinformation by teaching them media literacy skills: verifying health claims, assessing the credibility of sources, understanding the economic factors that drive misinformation, and recognising the marketing techniques influencers use to manipulate."],learningObjectives_es:["Fomentar el pensamiento cr\xedtico entre los estudiantes.","Reflexionar sobre el uso que hacemos de las redes sociales y el nivel de veracidad que otorgamos a los contenidos que vemos en ellas.","Cuestionar el rol e influencia que los y las influencers tienen en nosotros.","Prevenir que la juventud caiga en desinformaciones, reduciendo as\xed la propagaci\xf3n y el impacto de los bulos ense\xf1\xe1ndoles habilidades de alfabetizaci\xf3n medi\xe1tica como: t\xe9cnicas de verificaci\xf3n sobre afirmaciones de salud, evaluaci\xf3n de la credibilidad de las fuentes de informaci\xf3n, comprender los factores econ\xf3micos que impulsan la desinformaci\xf3n o reconocer las t\xe9cnicas de marketing que los influencers utilizan para manipular."],learningObjectives_fi:["Kannustaa opiskelijoita kriittiseen ajatteluun.","Pohtia, miten k\xe4yt\xe4mme sosiaalista mediaa ja kuinka totuudenmukaisina pid\xe4mme sen sis\xe4lt\xf6\xe4.","Kyseenalaistaa vaikuttajien rooli ja vaikutusvalta meihin.","Est\xe4\xe4 nuoria joutumasta v\xe4\xe4r\xe4n tiedon uhreiksi opettamalla heille medialukutaitoa: tekniikoita terveysv\xe4itteiden tarkistamiseen, tietol\xe4hteiden luotettavuuden arviointiin, v\xe4\xe4r\xe4n tiedon taustalla olevien taloudellisten tekij\xf6iden ymm\xe4rt\xe4miseen ja vaikuttajien k\xe4ytt\xe4mien manipuloivien markkinointitekniikoiden tunnistamiseen."],learningObjectives_sr:["Podsticanje kritičkog mišljenja kod učenika.","Promišljanje o upotrebi društvenih mreža i poverenju u sadržaje koje pratimo.","Propitivanje uloge i uticaja koje influenseri imaju na nas.","Osnažiti mlade da prepoznaju i odbace dezinformacije, tako što će savladati konkretne veštine medijske pismenosti – od provere izvora i zdravstvenih tvrdnji, do razumevanja ekonomskih i marketinških mehanizama koji stoje iza manipulacija na internetu."],keywords:["escape room","Media literacy","misinformation"],tags_en:["misinformation","influencers","health","nutrition"],tags_es:["desinformaci\xf3n","influencers","salud","alimentaci\xf3n"],tags_fi:["v\xe4\xe4r\xe4 tieto","vaikuttajat","terveys","ravitsemus"],tags_sr:["dezinformacije","influenseri","zdravlje","ishrana"],image:"/assets/images/EndgameBackground.png",claim_en:"Become the insider who uncovers the truth: stop misinformation.",claim_es:"Convi\xe9rtete en el infiltrado que destapa la verdad: frena la desinformaci\xf3n.",claim_fi:"Ryhdy sis\xe4piiril\xe4iseksi, joka paljastaa totuuden: lopeta v\xe4\xe4r\xe4n tiedon levitt\xe4minen.",claim_sr:"Postanite insajder koji otkriva istinu: zaustavite dezinformacije.",externalLink:"https://play.unity.com/en/games/3e199a2b-03aa-44c1-9ecd-5f9a308280cc/webgl-builds",internalLink:"/play/theClickTrap/index.html",resources:[{resourceName:"Teacher's Guide",resourceName_es:"Gu\xeda did\xe1ctica",resourceName_en:"Teacher's Guide",resourceName_sr:"Vodič za nastavnike",resourceName_fi:"Opettajan opas",additionalInfo:"Teacher's Guide for educators to facilitate the escaperoom activity",additionalInfo_es:"Gu\xeda did\xe1ctica para educadores para facilitar la actividad de escaperoom",additionalInfo_sr:"Vodič za nastavnike i edukatore kako bi se olakšala aktivnost u sobi za bekstvo",additionalInfo_fi:"Opettajan opas kouluttajille pakohuonetoiminnan helpottamiseksi",tag:"Docs",resourceLink_es:"/documents/ER1/ES_ENDGAME_GuiaDidactica.pdf",resourceLink_en:"/documents/ER1/EN_ENDGAME_TeachingMaterials.pdf",resourceLink_sr:"/documents/ER1/SRB_ENDGAME_NastavniMaterijali.pdf",resourceLink_fi:"/documents/ER1/FI_ENDGAME_OpettajanAineisto.pdf"}]},{escaperoomname:"echo",category:"escaperoom",theme_en:"media literacy",theme_es:"alfabetizaci\xf3n medi\xe1tica",theme_fi:"medialukutaito",theme_sr:"medijska pismenost",title_en:"ECHO",title_es:"ECHO",title_fi:"ECHO",title_sr:"ECHO",duration_en:"20 minutes",duration_es:"20 minutos",duration_fi:"20 minuuttia",duration_sr:"20 minuta",level_en:"easy",level_es:"f\xe1cil",level_fi:"helppo",level_sr:"lako",moreInfo_en:"more info",moreInfo_es:"m\xe1s info",moreInfo_fi:"lis\xe4tietoja",moreInfo_sr:"više informacija",longdescription_en:"There is a flood of misinformation flooding the ECHO social media network. You have to act as moderator and identify the bot accounts, the AI-generated content, and the misuses of AI.",longdescription_es:"Hay una inundaci\xf3n de desinformaci\xf3n que fluye por la red social ECHO. Tienes que actuar como moderador e identificar las cuentas de bots, el contenido generado por IA y los usos indebidos de la IA.",longdescription_fi:"ECHO-sosiaalisen median verkossa on tulva v\xe4\xe4r\xe4\xe4 tietoa. Sinun on toimittava moderaattorina ja tunnistettava bottitilit, teko\xe4lyn tuottama sis\xe4lt\xf6 ja teko\xe4lyn v\xe4\xe4rink\xe4yt\xf6t.",longdescription_sr:"Na društvenoj mreži ECHO se širi poplava dezinformacija. Morate djelovati kao moderator i identificirati bot račune, sadržaj generiran umjetnom inteligencijom i zloupotrebe umjetne inteligencije.",learningObjectives_en:["Encourage critical thinking among students.","Reflect on how we use social media and the level of truthfulness we attribute to the content we see on it.","Understand how a Large Language Model works and how it is used in social media.","Evaluate recommended uses of AI to generate information and content.","Detect patterns that are typical of bot accounts."],learningObjectives_es:["Fomentar el pensamiento cr\xedtico entre los estudiantes.","Reflexionar sobre c\xf3mo usamos las redes sociales y el grado de veracidad que atribuimos al contenido que vemos en ellas.","Comprender c\xf3mo funciona un modelo de lenguaje a gran escala y c\xf3mo se utiliza en las redes sociales.","Evaluar los usos recomendados de la IA para generar informaci\xf3n y contenido.","Detectar patrones t\xedpicos de cuentas bot."],learningObjectives_fi:["Kannustaa opiskelijoita kriittiseen ajatteluun.","Pohtia, miten k\xe4yt\xe4mme sosiaalista mediaa ja kuinka luotettavaksi pid\xe4mme siell\xe4 n\xe4kem\xe4\xe4mme sis\xe4lt\xf6\xe4.","Ymm\xe4rt\xe4\xe4, miten suuri kielimalli toimii ja miten sit\xe4 k\xe4ytet\xe4\xe4n sosiaalisessa mediassa.","Arvioida teko\xe4lyn suositeltuja k\xe4ytt\xf6tapoja tiedon ja sis\xe4ll\xf6n tuottamisessa.","Tunnistaa bottitileille tyypillisi\xe4 malleja."],learningObjectives_sr:["Podsticati kritičko mišljenje kod učenika.","Razmišljati o tome kako koristimo društvene mreže i nivou istinitosti koji pripisujemo sadržaju koji na njima vidimo.","Razumeti kako funkcioniše LLM i kako se koristi u društvenim mrežama.","Proceniti preporučene načine korišćenja AI-a za generisanje informacija i sadržaja.","Prepoznati obrasce koji su tipični za bot naloge."],keywords:["escape room","Media literacy","misinformation","AI"],tags_en:["AI","social media","bots","misinformation in crisis situations"],tags_es:["IA","redes sociales","bots","desinformaci\xf3n en situaciones de crisis"],tags_fi:["teko\xe4ly","sosiaalinen media","botit","v\xe4\xe4r\xe4 informaatio kriisitilanteissa"],tags_sr:["veštačka inteligencija","društvene mreže","botovi","dezinformacija u kriznim situacijama"],image:"/assets/images/echo.png",claim_en:"Stop the flood of misinformation on ECHO: identify bots, AI content, and misuse of AI.",claim_es:"Det\xe9n la inundaci\xf3n de desinformaci\xf3n en ECHO: identifica bots, contenido de IA y mal uso de la IA.",claim_fi:"Est\xe4 v\xe4\xe4r\xe4n tiedon tulva ECHO:ssa: tunnista botit, teko\xe4lysis\xe4lt\xf6 ja teko\xe4lyn v\xe4\xe4rink\xe4ytt\xf6.",claim_sr:"Zaustavite poplavu dezinformacija na ECHO-u: identificirajte botove, AI sadržaj i zloupotrebu AI.",externalLink:"https://endgameproject.github.io/ECHO/",resources:[{resourceName:"Teacher's Guide",resourceName_es:"Gu\xeda did\xe1ctica",resourceName_en:"Teacher's Guide",resourceName_sr:"Vodič za nastavnike",resourceName_fi:"Opettajan opas",additionalInfo:"Teacher's Guide for educators to facilitate the escaperoom activity",additionalInfo_es:"Gu\xeda did\xe1ctica para educadores para facilitar la actividad de escaperoom",additionalInfo_sr:"Vodič za nastavnike i edukatore kako bi se olakšala aktivnost u sobi za bekstvo",additionalInfo_fi:"Opettajan opas kouluttajille pakohuonetoiminnan helpottamiseksi",tag:"Docs",resourceLink_es:"/documents/ER2/ES_ENDGAME_ER2_TeachingMaterials.pdf",resourceLink_en:"/documents/ER2/EN_ENDGAME_ER2_TeachingMaterials.pdf",resourceLink_sr:"/documents/ER2/SR_ENDGAME_ER2_TeachingMaterials.pdf",resourceLink_fi:"/documents/ER2/FI_ENDGAME_ER2_TeachingMaterials.pdf"}]},{escaperoomname:"lastchance",category:"escaperoom",theme_en:"media literacy",theme_es:"alfabetizaci\xf3n medi\xe1tica",theme_fi:"medialukutaito",theme_sr:"medijska pismenost",title_en:"LASTCHANCE",title_es:"LASTCHANCE",title_fi:"LASTCHANCE",title_sr:"LASTCHANCE",duration_en:"40 minutes",duration_es:"40 minutos",duration_fi:"40 minuuttia",duration_sr:"40 minuta",level_en:"intermediate",level_es:"intermedio",level_fi:"keskitaso",level_sr:"srednji",moreInfo_en:"more info",moreInfo_es:"m\xe1s info",moreInfo_fi:"lis\xe4tietoja",moreInfo_sr:"više informacija",longdescription_en:"Your friend is about to fall for an online scam and you are their last chance to stop it. To help them, you will dive into a physical version of the internet, where tempting ads, too-good-to-be-true offers and websites that look legitimate but aren't are waiting for you. Gather clues, overcome challenges and learn to spot the tricks scammers and online advertising use to catch our attention… before it's too late for your friend.",longdescription_es:"Tu amigo est\xe1 a punto de caer en una estafa online y t\xfa eres su \xfaltima oportunidad para evitarlo. Para ayudarle, te adentrar\xe1s en una versi\xf3n f\xedsica de internet, donde te esperan anuncios tentadores, ofertas demasiado buenas para ser verdad y webs que parecen fiables pero no lo son. Recaba pistas, supera los retos y aprende a reconocer los trucos que usan los estafadores y la publicidad online para captar nuestra atenci\xf3n… antes de que sea demasiado tarde para tu amigo.",learningObjectives_en:["Encourage critical thinking among students.","Identify fraudulent URLs by their red flags: words bolted onto the real domain, http:// instead of https://, unusual domain endings, look-alike characters and misspelled brand names.","Recognise gamified bait and how game-like rewards keep someone playing and spending.","Identify undisclosed advertising in influencer content and interpret sponsorship labels.","Use reverse image search to tell a genuine product photo from an AI-generated one.","Explain how algorithmic targeting works, and that a profile — not a listening microphone — selects the adverts a person sees.","Read past an advert’s promise to its actual terms, such as a “free trial” that conceals an auto-renewing subscription.","Name the persuasion techniques used in advertising: FOMO, social proof, exaggeration, influencer endorsement, emotional appeal and urgency.","Recognise manufactured urgency as a pressure tactic designed to prompt action before thought.","Transfer this reasoning to a real decision, assembling evidence into an argument that persuades someone else."],learningObjectives_es:["Fomentar el pensamiento cr\xedtico entre los estudiantes.","Identificar URL fraudulentas a partir de las se\xf1ales de alerta concretas que las delatan: palabras a\xf1adidas despu\xe9s del nombre de dominio aut\xe9ntico, http:// en lugar de https://, terminaciones de dominio poco habituales, caracteres que imitan a otros y nombres de marcas mal escritos.","Reconocer los se\xf1uelos basados en mec\xe1nicas de juego y explicar c\xf3mo se dise\xf1an las recompensas propias de los juegos y la sensaci\xf3n de tener suerte para que una persona siga jugando y gastando.","Identificar la publicidad no declarada en el contenido de influencers e interpretar las etiquetas de transparencia publicitaria que indican un patrocinio.","Utilizar la b\xfasqueda inversa de im\xe1genes para distinguir una fotograf\xeda aut\xe9ntica de un producto de otra generada por IA o procedente de un banco de im\xe1genes.","Explicar c\xf3mo funciona la segmentaci\xf3n algor\xedtmica: c\xf3mo se combinan la edad, los intereses, el comportamiento y las inseguridades de una persona para crear un perfil, y c\xf3mo es ese perfil, y no un micr\xf3fono que escucha o un virus, el que determina los anuncios que ve.","Ir m\xe1s all\xe1 de la promesa de un anuncio y leer sus condiciones reales, como una \xabprueba gratuita\xbb que oculta una suscripci\xf3n con renovaci\xf3n autom\xe1tica.","Nombrar las t\xe9cnicas de persuasi\xf3n utilizadas en la publicidad: FOMO, prueba social, exageraci\xf3n, respaldo de influencers, apelaci\xf3n emocional y urgencia.","Reconocer la urgencia artificial, comprendiendo que una cuenta atr\xe1s es una t\xe1ctica de presi\xf3n dise\xf1ada para provocar una acci\xf3n antes de que haya tiempo para reflexionar.","Aplicar este razonamiento a una decisi\xf3n real, reuniendo pruebas para construir un argumento que convenza a otra persona de no caer en una estafa."],learningObjectives_fi:["Kannustaa opiskelijoita kriittiseen ajatteluun.","Tunnistaa petolliset verkko-osoitteet niist\xe4 varoitusmerkeist\xe4, jotka paljastavat ne: aidon verkkotunnuksen per\xe4\xe4n liitetyt sanat, http:// https://-osoitteen sijaan, ep\xe4tavalliset verkkotunnuksen p\xe4\xe4tteet, samann\xe4k\xf6iset merkit ja v\xe4\xe4rin kirjoitetut br\xe4ndinimet.","Havaita pelillistetty houkutin ja selitt\xe4\xe4, miten pelinomaiset palkinnot ja onnekkuuden tunne on rakennettu pit\xe4m\xe4\xe4n ihminen pelaamassa ja kuluttamassa.","Tunnistaa piilomainonta vaikuttajien sis\xe4ll\xf6ss\xe4 ja tulkita kaupallisen yhteisty\xf6n merkinn\xe4t.","K\xe4ytt\xe4\xe4 k\xe4\xe4nteist\xe4 kuvahakua erottaakseen aidon tuotekuvan teko\xe4lyn luomasta tai kuvapankkikuvasta.","Selitt\xe4\xe4, miten algoritminen kohdentaminen toimii: miten henkil\xf6n ik\xe4, kiinnostuksen kohteet, k\xe4ytt\xe4ytyminen ja ep\xe4varmuudet yhdistet\xe4\xe4n profiiliksi, ja miten juuri t\xe4m\xe4 profiili — eik\xe4 kuunteleva mikrofoni tai virus — valitsee h\xe4nelle n\xe4ytett\xe4v\xe4t mainokset.","Lukea mainoksen lupauksen l\xe4pi sen todellisiin ehtoihin, kuten “ilmaiseen kokeiluun”, joka k\xe4tkee automaattisesti uusiutuvan tilauksen.","Nimet\xe4 mainonnassa k\xe4ytetyt suostuttelutekniikat: FOMO, sosiaalinen todiste, liioittelu, vaikuttajan suositus, tunteisiin vetoaminen ja kiire.","Tunnistaa keinotekoinen kiire ja ymm\xe4rt\xe4\xe4, ett\xe4 ajastin on painostuskeino, joka on suunniteltu saamaan toimimaan ennen ajattelemista.","Siirt\xe4\xe4 t\xe4m\xe4 p\xe4\xe4ttely todelliseen p\xe4\xe4t\xf6kseen kokoamalla todisteet argumentiksi, joka saa toisen ihmisen olemaan lankeamatta huijaukseen."],learningObjectives_sr:["Podsticati kritičko mišljenje kod učenika.","Prepoznati prevarantske veb-adrese po konkretnim znacima za uzbunu koji ih odaju: reči zalepljene posle pravog imena domena, http:// umesto https://, neobični nastavci domena, znakovi koji slično izgledaju i pogrešno napisana imena brendova.","Prepoznati gejmifikovan mamac i objasniti kako su nagrade u stilu igre i osećaj sreće napravljeni da zadrže nekoga da igra i troši.","Prepoznati neobjavljeno reklamiranje u sadržaju influensera i tumačiti oznake o sponzorstvu.","Koristiti obrnutu pretragu slike da se razlikuje prava fotografija proizvoda od one koju je generisala veštačka inteligencija ili sa stok-sajta.","Objasniti kako funkcioniše algoritamsko ciljanje: kako se godine, interesovanja, ponašanje i nesigurnosti osobe spajaju u profil i kako taj profil — a ne mikrofon koji sluša ili virus — bira oglase koje ta osoba vidi.","Čitati dalje od obećanja oglasa, do njegovih stvarnih uslova, kao kod „besplatne probe“ koja krije pretplatu sa automatskim obnavljanjem.","Imenovati tehnike ubeđivanja koje se koriste u reklamiranju: FOMO, društveni dokaz, preuveličavanje, preporuka influensera, apelovanje na emocije i osećaj hitnosti.","Prepoznati proizveden osećaj hitnosti i razumeti da je tajmer taktika pritiska osmišljena da izazove postupanje pre razmišljanja.","Preneti ovo rasuđivanje na stvarnu odluku, sastavljajući dokaze u argument koji ubeđuje nekog drugog da ne padne na prevaru."],keywords:["escape room","Media literacy","scams","online ads","fraudulent websites"],tags_en:["scams","online ads","fake websites","persuasion techniques"],tags_es:["estafas","anuncios online","webs falsas","t\xe9cnicas de persuasi\xf3n"],tags_fi:["huijaukset","verkkomainokset","valesivustot","vaikuttamistekniikat"],tags_sr:["prevare","onlajn oglasi","lažni sajtovi","tehnike uveđivanja"],image:"/assets/images/er3map.png",claim_en:"Your friend's last chance: stop the online scam before it's too late.",claim_es:"La \xfaltima oportunidad de tu amigo: frena la estafa online antes de que sea tarde.",externalLink:"https://endgameproject.github.io/lastchance/",resources:[{resourceName:"Teacher's Guide",resourceName_es:"Gu\xeda did\xe1ctica",resourceName_en:"Teacher's Guide",resourceName_sr:"Vodič za nastavnike",resourceName_fi:"Opettajan opas",additionalInfo:"Teacher's Guide for educators to facilitate the escaperoom activity",additionalInfo_es:"Gu\xeda did\xe1ctica para educadores para facilitar la actividad de escaperoom",additionalInfo_sr:"Vodič za nastavnike i edukatore kako bi se olakšala aktivnost u sobi za bekstvo",additionalInfo_fi:"Opettajan opas kouluttajille pakohuonetoiminnan helpottamiseksi",tag:"Docs",resourceLink_es:"/documents/ER3/ES_ENDGAME_ER3_TeachingMaterials.pdf",resourceLink_en:"/documents/ER3/EN_ENDGAME_ER3_TeachingMaterials.pdf",resourceLink_sr:"/documents/ER3/EN_ENDGAME_ER3_TeachingMaterials.pdf",resourceLink_fi:"/documents/ER3/EN_ENDGAME_ER3_TeachingMaterials.pdf"}]}]}}]);